-- Free, isolated preparation. No authorization, job, cron or provider dispatch.
create table public.analysis_luna_multirest_sets(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),source_control_id uuid not null references public.analysis_jev_hybrid_controls(id),version text not null check(version='luna-multirest-evidence-v1'),
 body jsonb not null,body_sha256 text not null check(body_sha256~'^[a-f0-9]{64}$'),config_sha256 text not null,selector_sha256 text not null,cases_sha256 text not null,
 sealed_at timestamptz not null default now(),created_by uuid not null references auth.users(id),paid_enabled boolean not null default false check(not paid_enabled),production_enabled boolean not null default false check(not production_enabled),unique(source_control_id,version),unique(id,organization_id)
);
create table public.analysis_luna_multirest_cases(
 set_id uuid not null,organization_id uuid not null,position int not null check(position between 1 and 40),review_id uuid not null references public.reviews(id),establishment_id uuid not null references public.establishments(id),theme_key text not null,polarity text not null check(polarity in('positive','negative')),analysis_text_sha256 text not null,case_sha256 text not null,body jsonb not null,
 primary key(set_id,review_id),unique(set_id,position),foreign key(set_id,organization_id) references public.analysis_luna_multirest_sets(id,organization_id)
);
create table public.analysis_luna_multirest_reference_seals(
 id uuid primary key default gen_random_uuid(),set_id uuid not null unique,organization_id uuid not null,dataset_sha256 text not null,reference_sha256 text not null check(reference_sha256~'^[a-f0-9]{64}$'),body jsonb not null,
 annotation_model text not null check(annotation_model='GPT-6'),reference_type text not null check(reference_type='GPT6_AI_reference_not_independent_human_Gold'),sealed_at timestamptz not null default now(),created_by uuid not null references auth.users(id),
 foreign key(set_id,organization_id) references public.analysis_luna_multirest_sets(id,organization_id),unique(id,set_id,organization_id)
);
create table public.analysis_luna_multirest_references(
 set_id uuid not null,organization_id uuid not null,seal_id uuid not null,review_id uuid not null,theme_key text not null,analysis_text_sha256 text not null,choice text not null check(choice in('absent','positive','negative','both','uncertain')),justification text not null check(length(trim(justification))>0),
 primary key(set_id,review_id),foreign key(set_id,review_id) references public.analysis_luna_multirest_cases(set_id,review_id),foreign key(seal_id,set_id,organization_id) references public.analysis_luna_multirest_reference_seals(id,set_id,organization_id)
);
-- Empty future result storage, one response per case. There is no runner or spending grant.
create table public.analysis_luna_multirest_results(
 set_id uuid not null,organization_id uuid not null,seal_id uuid not null,review_id uuid not null,request_count int not null check(request_count=1),status text not null check(status in('completed','failed','billing_uncertain')),request_sha256 text not null,analysis_text_sha256 text not null,served_model text,response jsonb,response_sha256 text,parsed jsonb,input_tokens bigint check(input_tokens>=0),output_tokens bigint check(output_tokens>=0),cost_usd numeric check(cost_usd>=0),duration_ms bigint check(duration_ms>=0),error_code text,created_at timestamptz not null default now(),
 primary key(set_id,review_id),foreign key(set_id,review_id) references public.analysis_luna_multirest_cases(set_id,review_id),foreign key(seal_id,set_id,organization_id) references public.analysis_luna_multirest_reference_seals(id,set_id,organization_id)
);
do $$declare t text;begin foreach t in array array['analysis_luna_multirest_sets','analysis_luna_multirest_cases','analysis_luna_multirest_reference_seals','analysis_luna_multirest_references','analysis_luna_multirest_results'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);
 execute format('create policy luna_multi_org_read on public.%I for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=%I.organization_id and m.user_id=(select auth.uid()) and m.role in(''owner'',''admin'',''manager'')))',t,t);
 execute format('create trigger luna_multi_immutable before update or delete on public.%I for each row execute function public.pilot_evidence_immutable()',t);
 execute format('create index %I on public.%I(organization_id)',t||'_org',t);
end loop;end $$;
create index luna_multi_set_actor on public.analysis_luna_multirest_sets(created_by);
create index luna_multi_case_review on public.analysis_luna_multirest_cases(review_id);
create index luna_multi_case_est on public.analysis_luna_multirest_cases(establishment_id);
create index luna_multi_ref_actor on public.analysis_luna_multirest_reference_seals(created_by);
create index luna_multi_ref_seal on public.analysis_luna_multirest_references(seal_id,set_id,organization_id);
create index luna_multi_result_seal on public.analysis_luna_multirest_results(seal_id,set_id,organization_id);
create function public.save_luna_multirest_set(p_user uuid,p_body jsonb,p_sha text) returns uuid language plpgsql security invoker set search_path='' as $$
declare src public.analysis_jev_hybrid_controls;sid uuid;x jsonb;origin jsonb;content jsonb;
begin
 select * into src from public.analysis_jev_hybrid_controls where id='4942bc5e-5790-4087-b382-ca4644d71f47';
 if src.id is null or not exists(select 1 from public.organization_members where organization_id=src.organization_id and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 if p_body->>'version' is distinct from 'luna-multirest-evidence-v1' or p_body->>'source_control_id' is distinct from src.id::text or p_body->>'organization_id' is distinct from src.organization_id::text or p_body->>'source_sha256' is distinct from src.result_sha256 or p_body->>'paid_enabled' is distinct from 'false' or p_body->>'production_enabled' is distinct from 'false' or p_body->>'new_paid_calls' is distinct from '0' or p_body->>'reference_count' is distinct from '0' or p_body->>'jev_reusable' is distinct from '0' or p_body->>'historical_overlap' is distinct from '0' or p_body->>'max_future_calls' is distinct from '40' or p_body->'config'->>'id' is distinct from 'luna-multirest-evidence-choice-v1' or p_body->'config'->>'model' is distinct from 'gpt-6-luna' or p_body->'config'->>'repeat_count' is distinct from '1' or p_body->'config'->>'paid_enabled' is distinct from 'false' or p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body),'sha256'),'hex') or p_body->>'config_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'config'),'sha256'),'hex') or p_body->>'cases_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body->'cases'),'sha256'),'hex') or jsonb_array_length(p_body->'cases')<>40 then raise exception 'MULTIREST_SET_INVALID';end if;
 if (select count(distinct it->>'review_id') from jsonb_array_elements(p_body->'cases') it)<>40 or (select count(distinct it->>'establishment_id') from jsonb_array_elements(p_body->'cases') it)<>11 then raise exception 'MULTIREST_COUNT_CHANGED';end if;
 for x in select value from jsonb_array_elements(p_body->'cases') loop
  select value into origin from jsonb_array_elements(src.body->'items') where value->>'review_id'=x->>'review_id';content:=x-'case_sha256';
  if origin is null or x->>'position' is distinct from origin->>'position' or x->>'establishment_id' is distinct from origin->>'establishment_id' or x->>'analysis_text' is distinct from origin->>'analysis_text' or x->>'original_text' is distinct from origin->>'original_text' or x->>'analysis_text_sha256' is distinct from origin->>'analysis_text_sha256' or x->>'original_text_sha256' is distinct from origin->>'original_text_sha256' or x->>'overall_rating' is distinct from origin->>'rating' or x->>'analysis_text_sha256' is distinct from encode(extensions.digest(x->>'analysis_text','sha256'),'hex') or x->>'case_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(content),'sha256'),'hex') or x->>'request_sha256' is distinct from encode(extensions.digest(public.jev_economy_canonical(x->'payload'),'sha256'),'hex') or not exists(select 1 from public.reviews r join public.establishments e on e.id=r.establishment_id where r.id=(x->>'review_id')::uuid and r.organization_id=src.organization_id and e.organization_id=src.organization_id and e.id=(x->>'establishment_id')::uuid) or exists(select 1 from public.analysis_decisions_evidence40_tasks where review_id=(x->>'review_id')::uuid) then raise exception 'MULTIREST_CASE_CHANGED';end if;
 end loop;
 perform pg_advisory_xact_lock(hashtextextended(src.id::text||':luna-multi-v1',0));
 select id into sid from public.analysis_luna_multirest_sets where source_control_id=src.id and version=p_body->>'version';
 if found then if not exists(select 1 from public.analysis_luna_multirest_sets where id=sid and body_sha256=p_sha) then raise exception 'MULTIREST_SET_IMMUTABLE';end if;return sid;end if;
 insert into public.analysis_luna_multirest_sets(organization_id,source_control_id,version,body,body_sha256,config_sha256,selector_sha256,cases_sha256,created_by) values(src.organization_id,src.id,p_body->>'version',p_body,p_sha,p_body->>'config_sha256',p_body->>'selector_sha256',p_body->>'cases_sha256',p_user) returning id into sid;
 for x in select value from jsonb_array_elements(p_body->'cases') loop
  insert into public.analysis_luna_multirest_cases(set_id,organization_id,position,review_id,establishment_id,theme_key,polarity,analysis_text_sha256,case_sha256,body) values(sid,src.organization_id,(x->>'position')::int,(x->>'review_id')::uuid,(x->>'establishment_id')::uuid,x->'candidate'->>'theme_key',x->'candidate'->>'polarity',x->>'analysis_text_sha256',x->>'case_sha256',x);
 end loop;return sid;
end $$;
create function public.seal_luna_multirest_references(p_user uuid,p_set uuid,p_body jsonb,p_sha text) returns uuid language plpgsql security invoker set search_path='' as $$
declare s public.analysis_luna_multirest_sets;sid uuid;x jsonb;
begin
 select * into s from public.analysis_luna_multirest_sets where id=p_set;
 if s.id is null or not exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=p_user and role in('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 if p_body->>'protocol' is distinct from s.version or p_body->>'dataset_sha256' is distinct from s.body_sha256 or p_body->>'annotation_model' is distinct from 'GPT-6' or p_body->>'reference_type' is distinct from 'GPT6_AI_reference_not_independent_human_Gold' or p_sha is distinct from encode(extensions.digest(public.jev_economy_canonical(p_body),'sha256'),'hex') or jsonb_array_length(p_body->'items')<>40 or (select count(distinct it->>'review_id') from jsonb_array_elements(p_body->'items') it)<>40 then raise exception 'MULTIREST_REFERENCE_INVALID';end if;
 for x in select value from jsonb_array_elements(p_body->'items') loop
  if x->>'choice' is null or x->>'choice' not in('absent','positive','negative','both','uncertain') or coalesce(length(trim(x->>'justification')),0)=0 or not exists(select 1 from public.analysis_luna_multirest_cases where set_id=s.id and review_id=(x->>'review_id')::uuid and theme_key=x->>'theme_key' and analysis_text_sha256=x->>'analysis_text_sha256') then raise exception 'MULTIREST_REFERENCE_ITEM_CHANGED';end if;
 end loop;
 perform pg_advisory_xact_lock(hashtextextended(s.id::text||':refs',0));
 select id into sid from public.analysis_luna_multirest_reference_seals where set_id=s.id;
 if found then if not exists(select 1 from public.analysis_luna_multirest_reference_seals where id=sid and reference_sha256=p_sha) then raise exception 'MULTIREST_REFERENCE_IMMUTABLE';end if;return sid;end if;
 insert into public.analysis_luna_multirest_reference_seals(set_id,organization_id,dataset_sha256,reference_sha256,body,annotation_model,reference_type,created_by) values(s.id,s.organization_id,s.body_sha256,p_sha,p_body,'GPT-6','GPT6_AI_reference_not_independent_human_Gold',p_user) returning id into sid;
 for x in select value from jsonb_array_elements(p_body->'items') loop
  insert into public.analysis_luna_multirest_references(set_id,organization_id,seal_id,review_id,theme_key,analysis_text_sha256,choice,justification) values(s.id,s.organization_id,sid,(x->>'review_id')::uuid,x->>'theme_key',x->>'analysis_text_sha256',x->>'choice',x->>'justification');
 end loop;return sid;
end $$;
revoke all on function public.save_luna_multirest_set(uuid,jsonb,text),public.seal_luna_multirest_references(uuid,uuid,jsonb,text) from public,anon,authenticated;
grant execute on function public.save_luna_multirest_set(uuid,jsonb,text),public.seal_luna_multirest_references(uuid,uuid,jsonb,text) to service_role;
create function public.luna_multirest_source_check() returns jsonb language sql security invoker set search_path='' as $fn$
 with src as(select * from public.analysis_jev_hybrid_controls where id='4942bc5e-5790-4087-b382-ca4644d71f47' and organization_id='93228bbb-6397-41e3-b8be-21ee7060eda7'), ids as(select (it->>'review_id')::uuid id from src cross join lateral jsonb_array_elements(body->'items') it), historical as(select review_id::text id from public.analysis_corrected_reference_labels union select review_id::text id from public.analysis_decisions_evidence40_tasks union select review_id::text id from public.analysis_decisions_tasks union select review_id::text id from public.analysis_gold_adjudication_events union select review_id::text id from public.analysis_gold_adjudication_items union select review_id::text id from public.analysis_gold_adjudication_labels union select review_id::text id from public.analysis_gold_events union select review_id::text id from public.analysis_gold_labels union select review_id::text id from public.analysis_gold_set_reviews union select review_id::text id from public.analysis_jev_compact_ai_references union select review_id::text id from public.analysis_jev_compact_items union select review_id::text id from public.analysis_jev_compact_tasks union select review_id::text id from public.analysis_jev_compact_texts union select review_id::text id from public.analysis_jev_exploratory_corrections union select review_id::text id from public.analysis_jev_exploratory_items union select review_id::text id from public.analysis_jev_exploratory_review_uses union select review_id::text id from public.analysis_jev_exploratory_tasks union select review_id::text id from public.analysis_jev_independent_ai_error_audits union select review_id::text id from public.analysis_jev_independent_tasks union select review_id::text id from public.analysis_jev_pilot_tasks union select review_id::text id from public.analysis_jev_review_cache union select review_id::text id from public.analysis_jev_v12_ai_miss_audits union select review_id::text id from public.analysis_jev_v12_tasks union select review_id::text id from public.analysis_jev_v13_fresh_ai_reference_notes union select review_id::text id from public.analysis_jev_v13_fresh_posthoc_ai_audits union select review_id::text id from public.analysis_jev_v13_tasks union select review_id::text id from public.analysis_negative_ai_exploratory_tasks union select review_id::text id from public.analysis_negative_ai_review_rechecks union select review_id::text id from public.analysis_negative_ai_theme_rechecks union select review_id::text id from public.analysis_negative_validation_ai_preannotations union select review_id::text id from public.analysis_negative_validation_labels union select review_id::text id from public.analysis_negative_validation_reviews union select review_id::text id from public.analysis_negative_validation_tasks union select review_id::text id from public.analysis_representative_human_events union select review_id::text id from public.analysis_representative_human_labels union select review_id::text id from public.analysis_representative_human_test_items union select review_id::text id from public.analysis_v11_independent_holdout_ai_references union select review_id::text id from public.analysis_v11_independent_holdout_items union select review_id::text id from public.analysis_v9_finding_audit_items union select it->>'review_id' id from public.analysis_jev_pilot_evidence_v3_controls c cross join lateral jsonb_array_elements(c.body->'items') it union select it->>'review_id' id from public.analysis_jev_hybrid_controls c cross join lateral jsonb_array_elements(c.body->'items') it where c.id<>'4942bc5e-5790-4087-b382-ca4644d71f47' union select it->>'review_id' id from public.analysis_decisions_experiments c cross join lateral jsonb_array_elements(c.body->'evidence_verification'->'items') it)
 select jsonb_build_object('control',(select to_jsonb(src) from src),'identities',(select jsonb_agg(jsonb_build_object('id',r.id,'organization_id',r.organization_id,'establishment_id',r.establishment_id,'original_text',r.original_text,'original_language',r.original_language)) from public.reviews r join ids on ids.id=r.id),'establishments',(select jsonb_agg(jsonb_build_object('id',e.id,'organization_id',e.organization_id,'name',e.name)) from public.establishments e where e.id in(select r.establishment_id from public.reviews r join ids on ids.id=r.id)),'historical_ids',(select coalesce(jsonb_agg(distinct h.id),'[]'::jsonb) from historical h join ids on ids.id::text=h.id),'cache_ids',(select coalesce(jsonb_agg(c.review_id::text),'[]'::jsonb) from public.analysis_jev_review_cache c join ids on ids.id=c.review_id));
$fn$;
revoke all on function public.luna_multirest_source_check() from public,anon,authenticated;
grant execute on function public.luna_multirest_source_check() to service_role;
